parameters.jsCode:
const baseConfig = $('⚙️ Config Global1').first().json;
let aiOutput = items[0].json.output;

if (typeof aiOutput === 'string') {
  const clean = aiOutput.replace(/```json/g, '').replace(/```/g, '').trim();
  aiOutput = JSON.parse(clean);
}

const candidates = Array.isArray(aiOutput?.seed_keywords) ? aiOutput.seed_keywords : [];
const deduped = [];
const seen = new Set();

for (const entry of candidates) {
  const keyword = String(entry?.keyword || entry?.seed_keyword || entry || '').trim().toLowerCase();
  if (!keyword || seen.has(keyword)) continue;
  seen.add(keyword);
  deduped.push({
    keyword,
    angle: entry?.angle || null,
    reasoning: entry?.reasoning || ''
  });
}

if (deduped.length < 3) {
  throw new Error('O AI Seed Optimizer não retornou ao menos 3 seeds válidas.');
}

return deduped.slice(0, 5).map((seed, index) => ({
  json: {
    ...baseConfig,
    output: aiOutput,
    seed_keyword: seed.keyword,
    seed_angle: seed.angle,
    seed_reasoning: seed.reasoning,
    seed_rank: index + 1,
    loop_iteration: 0,
    max_loops: Number(baseConfig.max_loops || 5),
    min_volume_gold: Number(baseConfig.min_volume_gold || 10),
    master_bank: '[]',
    used_seeds: '[]',
    used_seeds_norm: '[]'
  }
}));

const MICROS = 1_000_000;

const normalizeSeed = (s) => {
  return String(s || '')
    .toLowerCase()
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .split(/\s+/)
    .filter(Boolean)
    .sort()
    .join(' ');
};

const input = items[0].json;

const rawResults = Array.isArray(input.results) ? input.results : [];

const currentLoop = Number(input.loop_iteration) || 0;
const maxLoops = Number(input.max_loops) || 5;
const minVolumeGold = Number(input.min_volume_gold) || 10;
const currentSeed = String(input.seed_keyword || '').toLowerCase().trim();
const currentSeedNorm = normalizeSeed(currentSeed);

let masterBank = [];
if (typeof input.master_bank === 'string') {
  try { masterBank = JSON.parse(input.master_bank || '[]'); } catch {}
} else if (Array.isArray(input.master_bank)) {
  masterBank = input.master_bank;
}
if (!Array.isArray(masterBank)) masterBank = [];

let usedSeeds = [];
if (typeof input.used_seeds === 'string') {
  try { usedSeeds = JSON.parse(input.used_seeds || '[]'); } catch {}
} else if (Array.isArray(input.used_seeds)) {
  usedSeeds = input.used_seeds;
}
if (!Array.isArray(usedSeeds)) usedSeeds = [];

let usedSeedsNorm = [];
if (typeof input.used_seeds_norm === 'string') {
  try { usedSeedsNorm = JSON.parse(input.used_seeds_norm || '[]'); } catch {}
} else if (Array.isArray(input.used_seeds_norm)) {
  usedSeedsNorm = input.used_seeds_norm;
}
if (!Array.isArray(usedSeedsNorm)) usedSeedsNorm = [];

if (currentSeed && !usedSeeds.includes(currentSeed)) {
  usedSeeds.push(currentSeed);
}
if (currentSeedNorm && !usedSeedsNorm.includes(currentSeedNorm)) {
  usedSeedsNorm.push(currentSeedNorm);
}

const extracted = rawResults
  .map(item => {
    const m = item.keywordIdeaMetrics || {};
    const kw = String(item.text || '').toLowerCase().trim();
    if (!kw) return null;

    return {
      keyword: kw,
      volume: Number(m.avgMonthlySearches) || 0,
      cpc: Number(((Number(m.averageCpcMicros) || 0) / MICROS).toFixed(2)),
      low_bid: Number(((Number(m.lowTopOfPageBidMicros) || 0) / MICROS).toFixed(2)),
      high_bid: Number(((Number(m.highTopOfPageBidMicros) || 0) / MICROS).toFixed(2)),
      competition: String(m.competition || 'UNKNOWN').toUpperCase(),
      competition_index: Number(m.competitionIndex) || 0,
      found_in_loop: currentLoop,
      seed_origin: currentSeed
    };
  })
  .filter(Boolean);

const bankMap = new Map();

for (const kw of masterBank) {
  if (kw?.keyword) bankMap.set(kw.keyword, kw);
}

for (const kw of extracted) {
  const existing = bankMap.get(kw.keyword);
  if (!existing || kw.volume > existing.volume) {
    bankMap.set(kw.keyword, kw);
  }
}

const updatedBank = Array.from(bankMap.values());

const golds = updatedBank
  .filter(k => {
    if ((k.volume || 0) < minVolumeGold) return false;
    const kwNorm = normalizeSeed(k.keyword);
    return !usedSeedsNorm.includes(kwNorm);
  })
  .sort((a, b) => (b.volume || 0) - (a.volume || 0));

const nextSeed = golds.length > 0 ? golds[0].keyword : null;

const shouldContinue =
  !!nextSeed &&
  normalizeSeed(nextSeed) !== currentSeedNorm &&
  currentLoop < (maxLoops - 1) &&
  extracted.length > 0;

const newKeywords = extracted.filter(
  k => !masterBank.some(m => m.keyword === k.keyword)
).length;

return [{
  json: {
    loop: {
      current: currentLoop,
      max: maxLoops,
      should_continue: shouldContinue,
      next_seed: nextSeed,
      reason: !shouldContinue
        ? (currentLoop >= (maxLoops - 1) ? 'MAX_LOOPS_REACHED'
          : !nextSeed ? 'NO_MORE_GOLDS'
          : extracted.length === 0 ? 'API_EMPTY'
          : 'DUPLICATE_SEED_NORM')
        : 'GOLD_FOUND'
    },

    master_bank: updatedBank,
    master_bank_json: JSON.stringify(updatedBank),

    used_seeds: usedSeeds,
    used_seeds_json: JSON.stringify(usedSeeds),

    used_seeds_norm: usedSeedsNorm,
    used_seeds_norm_json: JSON.stringify(usedSeedsNorm),

    iteration_stats: {
      loop_number: currentLoop,
      seed_used: currentSeed,
      all_seeds_used: usedSeeds,
      api_results: rawResults.length,
      new_keywords: newKeywords,
      bank_before: masterBank.length,
      bank_after: updatedBank.length,
      golds_remaining: golds.length,
      top_5_golds: golds.slice(0, 5).map(g => `${g.keyword} (${g.volume})`)
    },

    config: {
      mcc_id: input.mcc_id,
      customer_id: input.customer_id,
      developer_token: input.developer_token,
      geo_target: input.geo_target,
      language_constant: input.language_constant,
      language_code: input.language_code,
      language_short: input.language_short,
      nicho: input.nicho,
      'país_geo': input['país_geo'],
      max_loops: maxLoops,
      min_volume_gold: minVolumeGold
    }
  }
}];

// ================================================================
// 🧠 MASTER CONSOLIDATOR V2 — PRODUCTION READY
// ================================================================

const safeParse = (val) => {
  if (!val) return [];
  if (Array.isArray(val)) return val;
  if (typeof val === 'string') {
    try { return JSON.parse(val); } catch { return []; }
  }
  return [];
};

// 🔥 NORMALIZAÇÃO FORTE (anti-duplicado real)
const normalize = (s) =>
  String(s || '')
    .toLowerCase()
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // remove acento
    .replace(/[^\w\s]/g, '') // remove símbolos
    .split(/\s+/)
    .sort()
    .join(' ');

// --- INPUT ---
const allRuns = items.map(i => i.json);

if (allRuns.length === 0) {
  throw new Error('Nenhum item recebido do DONE.');
}

// 🔥 CONFIG SAFE (pega o mais completo)
const baseConfig = allRuns.find(r => r.geo_target || r.language_code) || allRuns[0];

// --- MAPS ---
const buildMap = new Map();
const validationMap = new Map();
const reports = [];

// ================================================================
// 🔄 LOOP
// ================================================================
for (const run of allRuns) {
  const masterBank = safeParse(run.master_bank);

  reports.push({
    seed: run.seed_keyword,
    loop: run.loop_iteration,
    bank_size: masterBank.length
  });

  for (const kw of masterBank) {
    const key = normalize(kw.keyword);
    if (!key) continue;

    const normalized = {
      keyword: kw.keyword,
      volume: kw.volume || 0,
      cpc: kw.cpc || 0,
      low_bid: kw.low_bid || 0,
      high_bid: kw.high_bid || 0,
      competition: kw.competition || 'UNKNOWN',
      competition_index: kw.competition_index || 0,
      seed_origin: kw.seed_origin || run.seed_keyword,
      found_in_loop: kw.found_in_loop ?? run.loop_iteration,
      variants: []
    };

    const existing = buildMap.get(key);

    if (!existing) {
      buildMap.set(key, normalized);
      continue;
    }

    if (normalized.volume > existing.volume) {
      normalized.variants = [...new Set([
        ...(existing.variants || []),
        existing.keyword,
        normalized.keyword
      ])];

      buildMap.set(key, normalized);
    } else {
      existing.variants = [...new Set([
        ...(existing.variants || []),
        normalized.keyword
      ])];
    }
  }

  // VALIDATION
  for (const kw of masterBank) {
    const key = normalize(kw.keyword);
    if (!key) continue;

    const volume = kw.volume || 0;
    const existing = validationMap.get(key);

    if (!existing || volume > existing.volume) {
      validationMap.set(key, {
        keyword: kw.keyword,
        volume
      });
    }
  }
}

// ================================================================
// 📊 FINAL
// ================================================================

const build_queue = Array.from(buildMap.values())
  .sort((a, b) => b.volume - a.volume);

let validation_keywords = Array.from(validationMap.values())
  .sort((a, b) => b.volume - a.volume);

// fallback
if (validation_keywords.length === 0) {
  validation_keywords = build_queue.map(item => ({
    keyword: item.keyword,
    volume: item.volume
  }));
}

// ================================================================
// 🧾 REPORT
// ================================================================

const master_report = [
  `🧠 KEYWORD ENGINE CONSOLIDATION`,
  `================================`,
  ``,
  `Seed base: ${baseConfig.seed_keyword}`,
  `Loops executados: ${Math.max(...allRuns.map(r => r.loop_iteration || 0)) + 1}`,
  `Seeds processadas: ${allRuns.length}`,
  `Keywords únicas: ${build_queue.length}`,
  ``,
  `TOP 10:`,
  ...build_queue.slice(0, 10).map(k =>
    `- ${k.keyword} (${k.volume})`
  )
].join('\n');

// ================================================================
// 🚀 OUTPUT
// ================================================================

return [{
  json: {
    ...baseConfig,

    build_queue,
    validation_keywords,

    master_report,
    loop_runs: reports,

    stats: {
      seeds_processed: allRuns.length,
      total_unique_keywords: build_queue.length,
      validation_keywords: validation_keywords.length
    }
  }
}];

// ================================================================
// 🧠 VALIDATION QUEUE BUILDER — SINGLE ITEM OUTPUT
// ================================================================

// --- INPUT PRINCIPAL ---
const data = items[0].json;

// --- CONFIG GLOBAL (fallback seguro) ---
let configGlobal = {};
try {
  configGlobal = $('⚙️ Config Global1').first().json;
} catch (e) {
  configGlobal = {};
}

// --- HELPERS ---
const get = (field) => {
  return data[field] ?? configGlobal[field] ?? null;
};

// --- DEFINE QUEUE ---
const queue = Array.isArray(data.validation_keywords) && data.validation_keywords.length > 0
  ? data.validation_keywords
  : (data.build_queue || []).map(item => ({
      keyword: item.keyword,
      volume: item.metrics?.volume || 0
    }));

// --- BUILD FINAL LIST ---
const validation_queue = queue.map((entry, index) => ({
  nicho: entry.keyword,

  geo_target: get('geo_target'),
  language_code: get('language_code'),
  language_short: get('language_short'),
  language_constant: get('language_constant'),
  país_geo: get('país_geo'),

  validation_rank: index + 1,
  validation_volume: entry.volume || 0
}));

// --- OUTPUT SINGLE ITEM ---
return [{
  json: {
    ...data,
    validation_queue,
    validation_total: validation_queue.length
  }
}];

