// ========================================
// 🔧 EXTRATOR: Google Autocomplete (Fix V2)
// Captura sugestões sem travar em tipos específicos
// ========================================

const data = items[0].json;
const tasks = data?.tasks || [];

const keywords = [];

for (const task of tasks) {
    // Verificação de segurança se o resultado existe
    if (!task.result || task.result.length === 0) continue;

    const items_list = task.result[0].items || [];

    for (const item of items_list) {
        // Tenta pegar o texto em várias propriedades possíveis da API
        const text = item.keyword || item.suggestion || item.title;

        // Se encontrou texto e ele é válido
        if (text && typeof text === 'string') {
            keywords.push({
                keyword: text.trim(), // Remove espaços extras
                volume: 0,            // Autocomplete não traz volume, o Merger resolve depois
                cpc: 0,
                low_bid: 0,
                high_bid: 0,
                competition: 'UNKNOWN',
                competition_index: 0,
                monthly_searches: [],
                source: 'google_autocomplete', // Marca a origem
                original_type: item.type,      // Guarda o tipo original pra debug
                needs_enrichment: true         // Avisa o Merger que precisa de dados
            });
        }
    }
}

// Deduplicação (Remove duplicatas exatas)
const unique = [...new Map(keywords.map(k => [k.keyword.toLowerCase(), k])).values()];

return [{ 
    json: { 
        keywords: unique, 
        count: unique.length,
        debug_first_item: keywords[0] // Pra você ver se deu certo
    } 
}];

// ========================================
// EXTRATOR: Related Keywords Labs
// ========================================

const data = items[0].json;
const items_list = data?.tasks?.[0]?.result?.[0]?.items || [];

const keywords = items_list.map(item => {
  const info = item.keyword_data?.keyword_info || {};
  return {
    keyword: item.keyword_data?.keyword || item.keyword,
    volume: info.search_volume || 0,
    cpc: info.cpc || 0,
    low_bid: info.low_top_of_page_bid || 0,
    high_bid: info.high_top_of_page_bid || 0,
    competition: info.competition_level || 'UNKNOWN',
    competition_index: info.competition_index || 0,
    monthly_searches: info.monthly_searches || [],
    source: 'related_keywords_labs'
  };
});

return [{ json: { keywords, count: keywords.length } }];

// ================================================================
// 🔀 MEGA MERGE — STATE OF THE ART v2.0
// ================================================================

const inputs = $input.all();

// ================================================================
// 🧠 EXTRAÇÃO INTELIGENTE POR ESTRUTURA
// ================================================================
let autocompleteKeywords = [];
let enrichedKeywords = [];
let controlState = null;

for (const item of inputs) {
  const json = item.json;

  // Detecta pelo fingerprint da estrutura
  if (Array.isArray(json.keywords) && json.keywords.length > 0) {

    const sample = json.keywords[0];

    // ITEM AUTOCOMPLETE: needs_enrichment = true, sem monthly_searches
    if (sample.needs_enrichment === true || sample.source === 'google_autocomplete') {
      autocompleteKeywords.push(...json.keywords);
    }
    // ITEM ENRIQUECIDO: tem volume real ou source diferente
    else {
      enrichedKeywords.push(...json.keywords);
    }

  }
  // ITEM CONTROLE: tem master_bank ou build_queue ou validation_queue
  else if (json.master_bank || json.build_queue || json.validation_queue || json.loop_runs) {
    controlState = json;
  }
}

// ================================================================
// 🔗 MERGE KEYWORDS: enriquecidas ganham, autocomplete preenche gaps
// ================================================================
const enrichedMap = new Map();
for (const kw of enrichedKeywords) {
  enrichedMap.set(kw.keyword.toLowerCase().trim(), kw);
}

// Adiciona autocomplete que NÃO existe no enriquecido
for (const kw of autocompleteKeywords) {
  const key = kw.keyword.toLowerCase().trim();
  if (!enrichedMap.has(key)) {
    enrichedMap.set(key, kw);
  }
}

const mergedKeywords = Array.from(enrichedMap.values());

// Ordena por volume desc
mergedKeywords.sort((a, b) => (b.volume || 0) - (a.volume || 0));

// ================================================================
// 🚀 OUTPUT FINAL
// ================================================================
return [
  {
    json: {
      keywords: mergedKeywords,
      total: mergedKeywords.length,
      control_state: controlState,
      debug: {
        inputs_received: inputs.length,
        autocomplete_raw: autocompleteKeywords.length,
        enriched_raw: enrichedKeywords.length,
        merged_unique: mergedKeywords.length,
        has_control_state: controlState !== null
      }
    }
  }
];

// ================================================================
