// ================================================================
// 🔧 HELPERS
// ================================================================

/** Checa se texto contém alguma palavra da lista */
function containsAny(text, words) {
  for (const w of words) {
    if (text.includes(w)) return true;
  }
  return false;
}

/** Detecta mês mencionado na keyword */
function detectMonth(text) {
  for (const month of UNIQUE_MONTHS) {
    if (text.includes(month)) return month;
  }
  return null;
}

/** Calcula trend score baseado em monthly_searches */
function trendScore(monthlySearches) {
  if (!Array.isArray(monthlySearches) || monthlySearches.length < 3) return 0;

  // Ordena cronologicamente
  const sorted = [...monthlySearches].sort((a, b) => {
    if (a.year !== b.year) return a.year - b.year;
    return a.month - b.month;
  });

  const len = sorted.length;
  const recent3 = sorted.slice(-3);
  const older3 = sorted.slice(0, 3);

  const avgRecent = recent3.reduce((s, x) => s + (x.search_volume || 0), 0) / recent3.length;
  const avgOlder = older3.reduce((s, x) => s + (x.search_volume || 0), 0) / older3.length;

  if (avgOlder === 0) return avgRecent > 0 ? 999 : 0;
  return Math.round(((avgRecent - avgOlder) / avgOlder) * 100);
}

/** Detecta pico sazonal */
function detectSeasonalPeak(monthlySearches) {
  if (!Array.isArray(monthlySearches) || monthlySearches.length < 6) return null;

  const max = monthlySearches.reduce((best, x) => 
    (x.search_volume || 0) > (best.search_volume || 0) ? x : best
  , monthlySearches[0]);

  const avg = monthlySearches.reduce((s, x) => s + (x.search_volume || 0), 0) / monthlySearches.length;

  if (max.search_volume > avg * 2.5) {
    return { month: max.month, year: max.year, spike_ratio: Math.round(max.search_volume / avg * 10) / 10 };
  }
  return null;
}

// ================================================================
// 🧠 MINERAÇÃO PRINCIPAL
// ================================================================
const goldMine = {
  titans: [],
  future: [],
  gems: [],
  hidden_trends: [],
  questions: [],
  seasonal: [],
  discards: []
};

for (const k of rawKeywords) {
  const vol = parseInt(k.volume) || 0;
  const cpc = parseFloat(k.cpc) || 0;
  const comp = (k.competition || '').toUpperCase();
  const monthly = k.monthly_searches || [];

  let kwText = (k.keyword || '').toLowerCase();
  let displayKeyword = k.keyword;
  const tags = [...(k.smart_tags || [])];
  const reliability = k.data_reliability || 'LOW';
  let warpReason = '';
  let warped = false;

  // =============================================================
  // ⏳ TIME WARP MULTILÍNGUE
  // Substitui anos passados pelo atual, EXCETO em contextos de
  // dívida/resultado/histórico
  // =============================================================
  for (const oldYear of CONFIG.years_warp) {
    if (kwText.includes(oldYear)) {
      const isExcluded = containsAny(kwText, DEBT_EXCLUSION_WORDS);

      if (!isExcluded) {
        const regex = new RegExp(oldYear, 'g');
        displayKeyword = displayKeyword.replace(regex, CY);
        kwText = displayKeyword.toLowerCase();
        tags.push('TIME_WARP');
        warpReason = ` [${oldYear}→${CY}]`;
        warped = true;
      } else {
        tags.push('HISTORICAL_REFERENCE');
      }
      break; // só faz warp uma vez
    }
  }

  // =============================================================
  // 📈 TREND ANALYSIS
  // =============================================================
  const trend = trendScore(monthly);
  const peak = detectSeasonalPeak(monthly);

  if (trend > 200) tags.push('EXPLOSIVE_TREND');
  else if (trend > 100) tags.push('STRONG_TREND');
  else if (trend > 50) tags.push('RISING');
  else if (trend < -50) tags.push('DECLINING');

  if (peak) {
    tags.push('SEASONAL');
  }

  // =============================================================
  // 📅 DETECÇÃO DE MÊS
  // =============================================================
  const detectedMonth = detectMonth(kwText);
  if (detectedMonth) tags.push('MONTH_SPECIFIC');

  // =============================================================
  // OBJETO PROCESSADO
  // =============================================================
  const processedKw = {
    keyword: displayKeyword,
    volume: vol,
    cpc: cpc,
    competition: comp,
    tags: tags,
    trend_score: trend,
    seasonal_peak: peak,
    reason: ''
  };

  let approvedForAds = false;

  // =============================================================
  // 🕵️ R1: QUESTÕES / INTENÇÃO INFORMACIONAL (Multilíngue)
  // =============================================================
  if (containsAny(kwText, QUESTION_WORDS)) {
    processedKw.tags.push('USER_QUESTION');
    goldMine.questions.push({ ...processedKw });
  }

  // =============================================================
  // 🕵️ R2: TENDÊNCIAS OCULTAS (Volume 0 + Autocomplete)
  // =============================================================
  if (vol === 0 && k.source === 'google_autocomplete') {
    processedKw.tags.push('HIDDEN_TREND');
    processedKw.reason = 'Google Autocomplete suggestion — no historical data yet.';
    goldMine.hidden_trends.push(processedKw);
    continue;
  }

  // =============================================================
  // 🚨 R3: DEAD KEYWORDS (Volume 0 validado)
  // =============================================================
  if (vol === 0 && reliability === 'HIGH') {
    goldMine.discards.push(displayKeyword + ' (vol=0 confirmed)');
    continue;
  }

  // =============================================================
  // 📅 R4: SEASONAL SPIKES
  // =============================================================
  if (peak && peak.spike_ratio > 3) {
    processedKw.tags.push('SEASONAL_SPIKE');
    processedKw.reason = `Seasonal spike ${peak.spike_ratio}x avg (M${peak.month})${warpReason}`;
    goldMine.seasonal.push({ ...processedKw });
  }

  // =============================================================
  // 🚀 R5: CLASSIFICAÇÃO PARA ADS
  // =============================================================

  // A. TITANS (>= 20k)
  if (vol >= CONFIG.volume_titan) {
    processedKw.tags.push('VOLUME_TITAN');
    processedKw.reason = `Massive Volume (${(vol / 1000).toFixed(0)}k)${warpReason}`;
    goldMine.titans.push(processedKw);
    approvedForAds = true;
  }

  // B. FUTURE / TEMPORAL TREND
  else if (CONFIG.years_target.some(y => kwText.includes(y))) {
    processedKw.tags.push('FUTURE_TREND');
    processedKw.reason = `Temporal Trend${warpReason}`;
    goldMine.future.push(processedKw);
    approvedForAds = true;
  }

  // C. SCALE OPPORTUNITY (5k-20k + CPC aceitável)
  else if (vol >= CONFIG.volume_scale && cpc <= CONFIG.max_cpc_scale) {
    processedKw.tags.push('SCALE_OPPORTUNITY');
    processedKw.reason = `Good Volume + Affordable CPC${warpReason}`;
    goldMine.gems.push(processedKw);
    approvedForAds = true;
  }

  // D. HIDDEN GEM (>= 1k + baixa competição)
  else if (vol >= CONFIG.volume_gem && (comp === 'LOW' || cpc < 0.20)) {
    processedKw.tags.push('HIDDEN_GEM');
    processedKw.reason = `Low Competition / Low Cost${warpReason}`;
    goldMine.gems.push(processedKw);
    approvedForAds = true;
  }

  // E. EXPLOSIVE MICRO (volume menor mas trend explosivo)
  else if (vol >= 100 && trend > 200) {
    processedKw.tags.push('EXPLOSIVE_MICRO');
    processedKw.reason = `Low volume but ${trend}% growth${warpReason}`;
    goldMine.gems.push(processedKw);
    approvedForAds = true;
  }

  // Descarte
  if (!approvedForAds && !processedKw.tags.includes('USER_QUESTION')) {
    goldMine.discards.push(displayKeyword);
  }
}

// ================================================================
// 📊 ORDENAÇÃO E DEDUP
// ================================================================
const sortByVol = (a, b) => (b.volume - a.volume) || (b.trend_score - a.trend_score);

const adsQueue = [
  ...goldMine.titans,
  ...goldMine.future,
  ...goldMine.gems
].sort(sortByVol);

const contentQueue = [
  ...goldMine.questions,
  ...goldMine.hidden_trends,
  ...goldMine.seasonal
];

// Dedup por keyword normalizada
const dedup = (arr) => {
  const map = new Map();
  for (const item of arr) {
    const key = item.keyword.toLowerCase().trim();
    if (!map.has(key) || (item.volume > (map.get(key).volume || 0))) {
      map.set(key, item);
    }
  }
  return Array.from(map.values());
};

const uniqueAds = dedup(adsQueue).slice(0, CONFIG.max_ads_queue);
const uniqueContent = dedup(contentQueue).slice(0, CONFIG.max_content_queue);

// ================================================================
// 🚀 OUTPUT
// ================================================================
return [{
  json: {
    summary: {
      total_analyzed: rawKeywords.length,
      ads_approved: uniqueAds.length,
      content_ideas: uniqueContent.length,
      year_context: {
        current: CY,
        last: LY,
        next: NY,
        warped_from: CONFIG.years_warp
      },
      breakdown: {
        titans: goldMine.titans.length,
        gems: goldMine.gems.length,
        future: goldMine.future.length,
        seasonal: goldMine.seasonal.length,
        hidden_trends: goldMine.hidden_trends.length,
        questions: goldMine.questions.length,
        discards: goldMine.discards.length
      },
      languages_supported: ['pt-br', 'es', 'en', 'fr', 'de', 'it']
    },

    // 💰 FILA DE ADS (anos corrigidos, ordenada por volume)
    production_ads_queue: uniqueAds,

    // ✍️ FILA DE CONTEÚDO (questões + trends + sazonais)
    content_seo_queue: uniqueContent
  }
}];

