// ================================================================
// 🏭 FUNNEL FACTORY: PREPARADOR DE LOTES (V7 - OUTPUT UNIFICADO)
// - 1 item por funil (batch_info embutido)
// - Pronto para Loop Over Items
// ================================================================

// 0. Configuração de Data
const CURRENT_DATE = new Date();
const CURRENT_YEAR = CURRENT_DATE.getFullYear();
const CURRENT_MONTH = CURRENT_DATE.getMonth() + 1;
const PREVIOUS_YEAR = CURRENT_YEAR - 1;

const MONTHS_PT = {
    'janeiro': 1, 'fevereiro': 2, 'março': 3, 'abril': 4,
    'maio': 5, 'junho': 6, 'julho': 7, 'agosto': 8,
    'setembro': 9, 'outubro': 10, 'novembro': 11, 'dezembro': 12
};

// 1. Funções de Tratamento
function processKeywordDate(keyword, volume) {
    let processed = keyword;

    if (processed.includes(String(PREVIOUS_YEAR))) {
        processed = processed.replace(new RegExp(String(PREVIOUS_YEAR), 'g'), String(CURRENT_YEAR));
    }

    const hasCurrentYear = processed.includes(String(CURRENT_YEAR));
    if (hasCurrentYear) {
        for (const [monthName, monthNum] of Object.entries(MONTHS_PT)) {
            if (processed.toLowerCase().includes(monthName) && monthNum < CURRENT_MONTH) {
                return { keyword: null, removed: true, reason: `Mês ${monthName} já passou` };
            }
        }
    }

    return { keyword: processed, removed: false, reason: null };
}

function deduplicateKeywords(keywords) {
    const seen = new Map();
    const result = [];

    for (const kw of keywords) {
        const normalized = kw.keyword.toLowerCase().trim();

        if (!seen.has(normalized)) {
            seen.set(normalized, kw);
            result.push(kw);
        } else {
            const existing = seen.get(normalized);
            if (kw.volume > existing.volume) {
                const idx = result.findIndex(k => k.keyword.toLowerCase().trim() === normalized);
                if (idx !== -1) {
                    result[idx] = kw;
                    seen.set(normalized, kw);
                }
            }
        }
    }

    return result;
}

// 2. Parse do Input
let aiOutput;
try {
    const rawContent = items[0].json.output;
    if (typeof rawContent === 'object') {
        aiOutput = rawContent;
    } else {
        const cleanString = rawContent.replace(/```json/g, "").replace(/```/g, "").trim();
        aiOutput = JSON.parse(cleanString);
    }
} catch (error) {
    throw new Error("Falha ao ler o JSON do Peneirador. Erro: " + error.message);
}

const funnels = aiOutput.funis_sugeridos || [];

// 3. Metadata do Batch (será embutido em cada funil)
const batchInfo = {
    total_funnels: funnels.length,
    processed_at: CURRENT_DATE.toISOString(),
    ano_referencia: CURRENT_YEAR,
    priorizacao: aiOutput.priorizacao || {},
    observacoes: aiOutput.observacoes || [],
    alertas_anti_canibalizacao: aiOutput.alertas_anti_canibalizacao || []
};

// 4. Processamento Principal - 1 ITEM POR FUNIL
const productionQueue = funnels.map(funnel => {

    const VOLUME_THRESHOLD = 20000;
    const MIN_ITEMS_PER_INTENT = 3;
    const MAX_ITEMS_PER_INTENT = 10;

    const subIntencoes = funnel.sub_intencoes || [];

    const allKeywordsForCampaign = [];
    const removedKeywords = [];

    const processedIntents = subIntencoes.map(intent => {
        const keywords = intent.keywords || [];

        const processedKws = [];
        for (const kw of keywords) {
            const result = processKeywordDate(kw.keyword, kw.volume);

            if (result.removed) {
                removedKeywords.push({
                    original: kw.keyword,
                    reason: result.reason,
                    volume_lost: kw.volume
                });
            } else {
                processedKws.push({
                    keyword: result.keyword,
                    volume: kw.volume,
                    cpc: kw.cpc,
                    original: kw.keyword !== result.keyword ? kw.keyword : null
                });
            }
        }

        const dedupedKws = deduplicateKeywords(processedKws);
        const sorted = [...dedupedKws].sort((a, b) => b.volume - a.volume);

        let selected = sorted.filter(k => k.volume >= VOLUME_THRESHOLD);
        if (selected.length < MIN_ITEMS_PER_INTENT) {
            selected = sorted.slice(0, Math.min(MAX_ITEMS_PER_INTENT, sorted.length));
        } else {
            selected = selected.slice(0, MAX_ITEMS_PER_INTENT);
        }

        dedupedKws.forEach(kw => {
            allKeywordsForCampaign.push({
                keyword: kw.keyword,
                volume: kw.volume,
                cpc: kw.cpc,
                sub_intencao: intent.tipo
            });
        });

        return {
            tipo: intent.tipo,
            descricao: intent.descricao || "",
            volume_sub: intent.volume_sub || 0,
            keywords: selected,
            keywords_text: selected
                .map(k => `  - ${k.keyword} (Vol: ${k.volume.toLocaleString('pt-BR')}, CPC: ${k.cpc.toFixed(2)})`)
                .join('\n')
        };
    });

    processedIntents.sort((a, b) => b.volume_sub - a.volume_sub);

    const finalCampaignKeywords = deduplicateKeywords(allKeywordsForCampaign);
    finalCampaignKeywords.sort((a, b) => b.volume - a.volume);

    const formattedSubIntents = processedIntents
        .map(intent => {
            return `📌 ${intent.tipo} (${intent.volume_sub.toLocaleString('pt-BR')} vol)\n${intent.descricao ? `   "${intent.descricao}"\n` : ''}${intent.keywords_text}`;
        })
        .join('\n\n');

    const keywordsForAds = finalCampaignKeywords
        .map(k => k.keyword)
        .join('\n');

    const keywordsForClickup = finalCampaignKeywords
        .map(k => `${k.keyword} | Vol: ${k.volume.toLocaleString('pt-BR')} | CPC: R$${k.cpc.toFixed(2)} | ${k.sub_intencao}`)
        .join('\n');

    const totalValidVolume = finalCampaignKeywords.reduce((sum, k) => sum + k.volume, 0);
    const totalLostVolume = removedKeywords.reduce((sum, k) => sum + k.volume_lost, 0);

    return {
        json: {
            // ✅ BATCH INFO EMBUTIDO
            _batch_info: batchInfo,

            project_name: funnel.nome_funil,
            execution_rank: funnel.rank,

            funnel_context: {
                theme: funnel.keyword_ancora,
                anchor_volume: funnel.volume_ancora || 0,

                metrics: {
                    total_volume: funnel.metricas?.volume_agregado || 0,
                    valid_volume: totalValidVolume,
                    lost_volume: totalLostVolume,
                    avg_cpc: funnel.metricas?.cpc_medio || 0,
                    total_keywords: funnel.metricas?.qtd_keywords || 0,
                    valid_keywords: finalCampaignKeywords.length,
                    removed_keywords: removedKeywords.length,
                    sub_intents_count: funnel.metricas?.qtd_sub_intencoes || processedIntents.length
                },

                strategic_direction: funnel.justificativa,
                tags: funnel.tags ? funnel.tags.join(", ") : "",

                sub_intencoes_raw: processedIntents,
                sub_intencoes_text: formattedSubIntents
            },

            keywords_campanha: {
                lista_google_ads: keywordsForAds,
                lista_clickup: keywordsForClickup,
                keywords_array: finalCampaignKeywords,
                stats: {
                    total_keywords: finalCampaignKeywords.length,
                    total_volume: totalValidVolume,
                    avg_cpc: finalCampaignKeywords.length > 0 
                        ? (finalCampaignKeywords.reduce((sum, k) => sum + k.cpc, 0) / finalCampaignKeywords.length).toFixed(2)
                        : 0
                }
            },

            keywords_removidas: {
                lista: removedKeywords,
                total_removidas: removedKeywords.length,
                volume_perdido: totalLostVolume
            },

            processamento: {
                data_processamento: CURRENT_DATE.toISOString(),
                ano_referencia: CURRENT_YEAR,
                mes_atual: CURRENT_MONTH,
                regras_aplicadas: [
                    `Substituição ${PREVIOUS_YEAR} → ${CURRENT_YEAR}`,
                    `Remoção de meses passados (< mês ${CURRENT_MONTH})`,
                    `Deduplicação por keyword normalizada`
                ]
            }
        }
    };
});

// 5. Ordenação por Prioridade e Retorno
productionQueue.sort((a, b) => a.json.execution_rank - b.json.execution_rank);

return productionQueue;

